import type {
  ComponentFamily,
  ComponentRole,
  LearnerActionFacet,
  LearningContextFacet,
  LearningPurposeFacet,
  RepresentationFacet,
  SubjectFacet,
} from "./taxonomy";

export type LocalizedText = string | Readonly<Record<string, string>>;

export type ConditionOperator =
  | "equals"
  | "not-equals"
  | "contains"
  | "not-contains"
  | "greater-than"
  | "less-than"
  | "is-set"
  | "is-not-set";

export interface AuthoringCondition {
  readonly path: string;
  readonly operator: ConditionOperator;
  readonly value?: string | number | boolean | readonly (string | number)[];
}

export type RequirednessLevel = "required" | "progressive" | "optional";

export interface ConditionalRequiredness {
  readonly level: RequirednessLevel;
  readonly when: AuthoringCondition;
}

/**
 * `true` and a bare condition are retained for backwards compatibility: they mean "required"
 * always and "required when the condition matches", respectively.
 */
export type Requiredness =
  | boolean
  | RequirednessLevel
  | AuthoringCondition
  | ConditionalRequiredness;

export interface AuthoringOption {
  readonly value: string;
  readonly label: LocalizedText;
  readonly description?: LocalizedText;
}

interface AuthoringFieldBase {
  readonly key: string;
  readonly label: LocalizedText;
  readonly description?: LocalizedText;
  readonly required?: Requiredness;
  readonly visibleWhen?: AuthoringCondition;
  readonly defaultValue?: unknown;
  readonly i18n?: boolean;
  readonly group?: string;
}

export interface TextAuthoringField extends AuthoringFieldBase {
  readonly kind: "text" | "rich-text";
  readonly minLength?: number;
  readonly maxLength?: number;
  readonly pattern?: string;
  readonly multiline?: boolean;
}

export interface NumberAuthoringField extends AuthoringFieldBase {
  readonly kind: "number";
  readonly min?: number;
  readonly max?: number;
  readonly step?: number;
  readonly unit?: LocalizedText;
}

export interface BooleanAuthoringField extends AuthoringFieldBase {
  readonly kind: "boolean";
}

export interface ChoiceAuthoringField extends AuthoringFieldBase {
  readonly kind: "select" | "multi-select";
  readonly options: readonly AuthoringOption[];
}

export interface AssetAuthoringField extends AuthoringFieldBase {
  readonly kind: "asset";
  readonly accept?: readonly string[];
  readonly altTextField?: string;
}

export interface ObjectAuthoringField extends AuthoringFieldBase {
  readonly kind: "object";
  readonly fields: readonly AuthoringField[];
}

export interface ListAuthoringField extends AuthoringFieldBase {
  readonly kind: "list";
  readonly item: AuthoringField;
  readonly minItems?: number;
  readonly maxItems?: number;
  readonly reorderable?: boolean;
}

export type AuthoringField =
  | TextAuthoringField
  | NumberAuthoringField
  | BooleanAuthoringField
  | ChoiceAuthoringField
  | AssetAuthoringField
  | ObjectAuthoringField
  | ListAuthoringField;

export interface AuthoringSchema {
  readonly version: string;
  readonly fields: readonly AuthoringField[];
  readonly supportsLocalization?: boolean;
}

export type EvidenceStrength = "high" | "moderate" | "low" | "not-evaluated";

export interface EvidenceReference {
  readonly id: string;
  readonly strength: EvidenceStrength;
  readonly citation: string;
  readonly url?: string;
  readonly claim: string;
  readonly limitations?: string;
}

export interface AccessibilityMetadata {
  readonly keyboard: "full" | "alternative" | "not-applicable" | "unsupported";
  readonly screenReader: "full" | "partial" | "not-applicable" | "unsupported";
  readonly draggingAlternative?: boolean;
  readonly requiresAltText?: boolean;
  readonly captions?: "required" | "recommended" | "not-applicable";
  readonly wcagCriteria?: readonly string[];
  readonly notes?: string;
}

export interface QtiMapping {
  readonly interaction: string;
  readonly fidelity: "exact" | "approximate" | "none";
  readonly version?: "3.0";
  readonly notes?: string;
}

export interface XapiMapping {
  readonly interactionType?:
    | "true-false"
    | "choice"
    | "fill-in"
    | "long-fill-in"
    | "matching"
    | "performance"
    | "sequencing"
    | "likert"
    | "numeric"
    | "other";
  readonly verbs?: readonly string[];
  readonly notes?: string;
}

export interface InteroperabilityMappings {
  readonly qti?: QtiMapping | readonly QtiMapping[];
  readonly xapi?: XapiMapping | readonly XapiMapping[];
}

export interface OptionalDependency {
  readonly package: string;
  readonly purpose: string;
  readonly requiredFor?: readonly string[];
  readonly fallback?: string;
}

export interface MigrationMetadata {
  readonly from: string;
  readonly to: string;
  readonly description: string;
  readonly breaking?: boolean;
}

export interface VersionMetadata {
  readonly schema: string;
  readonly component: string;
  readonly migrations?: readonly MigrationMetadata[];
}

export interface CatalogLifecycle {
  readonly availability: "available" | "planned" | "deprecated";
  readonly maturity: "draft" | "experimental" | "stable";
}

export interface ComponentVariant {
  readonly id: string;
  readonly name: LocalizedText;
  readonly description?: LocalizedText;
  readonly availability?: CatalogLifecycle["availability"];
}

export interface ComponentFacets {
  readonly subjects: readonly SubjectFacet[];
  readonly representations: readonly RepresentationFacet[];
  readonly learnerActions: readonly LearnerActionFacet[];
  readonly purposes: readonly LearningPurposeFacet[];
  readonly contexts?: readonly LearningContextFacet[];
}

export interface ComponentManifest {
  readonly id: string;
  readonly name: LocalizedText;
  readonly description: LocalizedText;
  readonly role: ComponentRole;
  readonly families: readonly ComponentFamily[];
  readonly facets: ComponentFacets;
  readonly lifecycle: CatalogLifecycle;
  readonly version: VersionMetadata;
  readonly authoring: AuthoringSchema;
  readonly evidence: readonly EvidenceReference[];
  readonly accessibility: AccessibilityMetadata;
  readonly mappings?: InteroperabilityMappings;
  readonly variants?: readonly ComponentVariant[];
  readonly optionalDependencies?: readonly OptionalDependency[];
  readonly capabilities?: readonly string[];
  readonly tags?: readonly string[];
}

export type CatalogCollectionKind = "foundation" | "subject" | "context" | "experience";
export type CatalogCollectionStatus = "draft" | "available" | "deprecated";
export type CollectionItemRole = "required" | "recommended" | "optional";

export interface CollectionItem {
  readonly manifestId: string;
  readonly typeId?: string;
  readonly role: CollectionItemRole;
  readonly reason: string;
}

export interface CatalogCollectionKit {
  readonly name: string;
  readonly includeRoles: readonly CollectionItemRole[];
}

export interface CatalogCollection {
  readonly id: string;
  readonly version: string;
  readonly slug: string;
  readonly title: LocalizedText;
  readonly description: LocalizedText;
  readonly kind: CatalogCollectionKind;
  readonly status: CatalogCollectionStatus;
  readonly facets?: Partial<ComponentFacets>;
  readonly items: readonly CollectionItem[];
  readonly kit?: CatalogCollectionKit;
  readonly tags?: readonly string[];
}

export type ResponseStatus = "draft" | "streaming" | "submitted";

interface ResponseBase {
  readonly id: string;
  readonly componentId: string;
  readonly status: ResponseStatus;
  readonly answeredAt?: string;
  readonly durationMs?: number;
}

export type Response = ResponseBase &
  (
    | { readonly kind: "choice"; readonly value: readonly string[] }
    | { readonly kind: "text"; readonly value: string }
    | { readonly kind: "numeric"; readonly value: number; readonly unit?: string }
    | { readonly kind: "boolean"; readonly value: boolean }
    | { readonly kind: "ordering"; readonly value: readonly string[] }
    | { readonly kind: "matching"; readonly value: Readonly<Record<string, string | readonly string[]>> }
    | { readonly kind: "points"; readonly value: readonly { readonly x: number; readonly y: number }[] }
    | { readonly kind: "file" | "audio" | "drawing"; readonly value: string }
    | { readonly kind: "composite"; readonly value: readonly Response[] }
  );

export interface Feedback {
  readonly kind: "informative" | "corrective" | "hint" | "explanation" | "model-answer";
  readonly message: LocalizedText;
  readonly target?: string;
  readonly priority?: "primary" | "secondary";
}

export interface Result {
  readonly responseId: string;
  readonly status: "ungraded" | "correct" | "incorrect" | "partial";
  readonly score?: number;
  readonly maxScore?: number;
  readonly normalizedScore?: number;
  readonly feedback?: readonly Feedback[];
  readonly outcomes?: Readonly<Record<string, string | number | boolean>>;
  readonly evaluatedAt?: string;
}

export interface ValidationIssue {
  readonly path: string;
  readonly code: string;
  readonly message: string;
  readonly severity: "error" | "warning";
}

export interface AuthoringValidationOptions {
  readonly mode: "complete" | "streaming";
}

export type ValidationResult<T> =
  | { readonly success: true; readonly data: T; readonly issues: readonly ValidationIssue[] }
  | { readonly success: false; readonly issues: readonly ValidationIssue[] };

import type { LocalizedText, ValidationIssue, ValidationResult } from "./types";

export const ARTIFACT_EXECUTION_SCHEMA_VERSION = "1.0.0" as const;

export type ArtifactKind = "code" | "text" | "data";
export type ArtifactExecutionMode = "none" | "sandboxed";

export interface ArtifactFileDefinition {
  id: string;
  path: string;
  kind: ArtifactKind;
  content: string;
  language?: string;
  mimeType?: string;
  readOnly?: boolean;
}

export interface ArtifactWorkspaceDefinition {
  schemaVersion: typeof ARTIFACT_EXECUTION_SCHEMA_VERSION;
  id: string;
  title: LocalizedText;
  description?: LocalizedText;
  instructions?: LocalizedText;
  files: ArtifactFileDefinition[];
  entryFileId?: string;
  execution: {
    mode: ArtifactExecutionMode;
    runtime?: string;
    timeoutMs?: number;
  };
  evaluation?: { enabled: boolean; allowWithoutExecution?: boolean };
}

export interface ArtifactOutputEntry {
  channel: "stdout" | "stderr" | "result";
  text: string;
}

export interface ArtifactExecutionResponse {
  status: "succeeded" | "failed";
  output: ArtifactOutputEntry[];
  durationMs?: number;
}

export interface ArtifactEvaluationResult {
  status: "correct" | "incorrect" | "partial" | "ungraded";
  score?: number;
  feedback?: LocalizedText;
  details?: Array<{ id: string; status: "passed" | "failed" | "info"; message: LocalizedText }>;
}

export interface ArtifactWorkspaceState {
  files: Record<string, string>;
  activeFileId?: string;
  executionStatus: "idle" | "running" | "succeeded" | "failed";
  execution?: ArtifactExecutionResponse;
  evaluation?: ArtifactEvaluationResult;
  revision: number;
}

export interface ArtifactExecutionRequest {
  definitionId: string;
  entryFileId?: string;
  runtime?: string;
  files: Record<string, string>;
}

export type ArtifactWorkspaceEvent =
  | { type: "file-selected"; fileId: string }
  | { type: "file-changed"; fileId: string }
  | { type: "execution-started" }
  | { type: "execution-completed"; status: "succeeded" | "failed" }
  | { type: "evaluation-completed"; status: ArtifactEvaluationResult["status"] }
  | { type: "reset" };

export function createArtifactWorkspaceState(definition: ArtifactWorkspaceDefinition): ArtifactWorkspaceState {
  return {
    files: Object.fromEntries(definition.files.map((file) => [file.id, file.content])),
    activeFileId: definition.entryFileId ?? definition.files[0]?.id,
    executionStatus: "idle",
    revision: 0,
  };
}

function issue(path: string, code: string, message: string): ValidationIssue {
  return { path, code, message, severity: "error" };
}

export function validateArtifactWorkspaceDefinition(value: unknown, options: { mode?: "complete" | "streaming" } = {}): ValidationResult<ArtifactWorkspaceDefinition> {
  const issues: ValidationIssue[] = [];
  if (!value || typeof value !== "object" || Array.isArray(value)) return { success: false, issues: [issue("$", "type", "Expected an artifact workspace definition.")] };
  const definition = value as Partial<ArtifactWorkspaceDefinition>;
  const required = (key: keyof ArtifactWorkspaceDefinition) => {
    if (definition[key] === undefined && options.mode !== "streaming") issues.push(issue(String(key), "required", `${String(key)} is required.`));
  };
  required("schemaVersion"); required("id"); required("title"); required("files"); required("execution");
  if (definition.schemaVersion !== undefined && definition.schemaVersion !== ARTIFACT_EXECUTION_SCHEMA_VERSION) issues.push(issue("schemaVersion", "value", "Unsupported schema version."));
  if (definition.id !== undefined && (typeof definition.id !== "string" || !definition.id.trim())) issues.push(issue("id", "type", "id must be a non-empty string."));
  if (definition.files !== undefined) {
    if (!Array.isArray(definition.files)) issues.push(issue("files", "type", "files must be an array."));
    else {
      const ids = new Set<string>(); const paths = new Set<string>();
      definition.files.forEach((file, index) => {
        const path = `files.${index}`;
        if (!file || typeof file !== "object") { issues.push(issue(path, "type", "Expected a file.")); return; }
        if (!file.id || !file.path || typeof file.content !== "string") issues.push(issue(path, "required", "File id, path and string content are required."));
        if (file.id && ids.has(file.id)) issues.push(issue(`${path}.id`, "unique", "File ids must be unique."));
        if (file.path && paths.has(file.path)) issues.push(issue(`${path}.path`, "unique", "File paths must be unique."));
        if (file.id) ids.add(file.id); if (file.path) paths.add(file.path);
      });
      if (definition.entryFileId && !ids.has(definition.entryFileId)) issues.push(issue("entryFileId", "reference", "entryFileId must reference a file."));
    }
  }
  if (definition.execution) {
    if (!(["none", "sandboxed"] as unknown[]).includes(definition.execution.mode)) issues.push(issue("execution.mode", "value", "Unknown execution mode."));
    if (definition.execution.mode === "sandboxed" && !definition.execution.runtime) issues.push(issue("execution.runtime", "required", "A sandboxed workspace requires a runtime identifier."));
    if (definition.execution.timeoutMs !== undefined && (!Number.isFinite(definition.execution.timeoutMs) || definition.execution.timeoutMs <= 0)) issues.push(issue("execution.timeoutMs", "range", "timeoutMs must be positive."));
  }
  return issues.length ? { success: false, issues } : { success: true, data: value as ArtifactWorkspaceDefinition, issues };
}

export function validateArtifactWorkspaceState(value: unknown, definition: ArtifactWorkspaceDefinition): ValidationResult<ArtifactWorkspaceState> {
  const issues: ValidationIssue[] = [];
  if (!value || typeof value !== "object" || Array.isArray(value)) return { success: false, issues: [issue("$", "type", "Expected workspace state.")] };
  const state = value as Partial<ArtifactWorkspaceState>;
  if (!state.files || typeof state.files !== "object" || Array.isArray(state.files)) issues.push(issue("files", "type", "files must be a record."));
  else for (const file of definition.files) if (typeof state.files[file.id] !== "string") issues.push(issue(`files.${file.id}`, "required", "Every definition file needs string content."));
  if (state.activeFileId && !definition.files.some(({ id }) => id === state.activeFileId)) issues.push(issue("activeFileId", "reference", "Unknown active file."));
  if (!(["idle", "running", "succeeded", "failed"] as unknown[]).includes(state.executionStatus)) issues.push(issue("executionStatus", "value", "Unknown execution status."));
  if (!Number.isInteger(state.revision) || Number(state.revision) < 0) issues.push(issue("revision", "range", "revision must be a non-negative integer."));
  return issues.length ? { success: false, issues } : { success: true, data: value as ArtifactWorkspaceState, issues };
}
